def compute(vars):
    common_equity = vars["v1"]
    basel_iii_cet1 = vars["v2"]
    net_adjustment = basel_iii_cet1 - common_equity

    return {
        "value": net_adjustment,
        "trace": {
            "common_equity": common_equity,
            "basel_iii_cet1": basel_iii_cet1,
            "net_adjustment": net_adjustment,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
